#include <stdio.h>
static int next_id(void) { static int value; return ++value; }
int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 20) return 1;
    for (int i=0; i<n; ++i) printf("%s%d", i ? " " : "", next_id());
    puts("");
    return 0;
}
